unit module RedSourcing::Storage;
use Red::DB;
use RedSourcing::EventType;
use RedSourcing::QueryTemplate;
use Red::AST::Value;
use JSON::Fast;
use Red::AST::Insert;
use Red::Type::Json;

# Storage models are flat, fixed schemas. Resolve their columns/inflators once,
# rather than reflecting over every column for every value of every result row.
# Alias/structural projections retain Red's ordinary materialization path.
role CachedStorageRows is export {
    has %!storage-row-columns;
    has @!storage-row-attributes;
    has @!full-row-sources;
    has @!full-row-inflators;

    method create-indexes(\model, |args) {
        callsame;
        my $driver = optimize-storage-driver(get-RED-DB);
        if model.^name eq 'RedSourcing::StoredEvent' && pg-driver($driver) {
            my @type = storage-query($driver, q[SELECT a.atttypid::regtype::text AS native
                FROM pg_attribute a WHERE a.attrelid = 'red_sourcing_event'::regclass
                AND a.attname = 'mro' AND NOT a.attisdropped]);
            die 'PostgreSQL MRO must be text[]; run tools/migrate-pg-mro-array.sql and restart the application'
                unless @type && @type.head<native> eq 'text[]';
            $driver.execute('CREATE INDEX IF NOT EXISTS red_sourcing_event_mro_gin ON '
                ~ $driver.table-name-wrapper(model.^table) ~ ' USING GIN (mro)');
        }
    }

    method cache-storage-columns(\model) {
        for model.^columns -> $attribute {
            $attribute.create-column;
            my $column = $attribute.column;
            @!storage-row-attributes.push($column.attr-name);
            my %descriptor = name => $column.attr-name, type => $column.attr.type,
                inflate => $column.inflate, arity => $column.inflate.count;
            %!storage-row-columns{$column.name} = %descriptor;
            %!storage-row-columns{$column.attr-name} = %descriptor;
            my $source = $column.name;
            my $target = $column.attr-name;
            my $type = $column.attr.type;
            my &inflate = $column.inflate;
            my &column-inflate = &inflate.count > 1
                ?? -> $value { inflate($value, $type) }
                !! -> $value { inflate($value) };
            @!full-row-sources.push($source);
            @!full-row-inflators.push(-> $data, $driver, %values {
                my $value = $data{$source};
                if $value.defined {
                    %values{$target} = $driver.inflate(column-inflate($value), :to($type));
                }
            });
        }
    }

    # Red's generic refresh constructs a structural projection of every column.
    # A full row is cheaper here and has exactly the same fixed storage schema.
    method refresh-storage-row(\model) {
        my $fresh = model.^rs.head;
        return model.^refresh unless $fresh.DEFINITE;
        model.^set-attr($_, $fresh."$_"()) for @!storage-row-attributes;
        model.^clean-up;
        model
    }

    method new-from-data(\model, $data) {
        return callsame unless model.^orig === model && $data ~~ Associative;
        my $driver = get-RED-DB;
        my %values;
        if $data.elems == @!full-row-sources.elems
                && @!full-row-sources.map({ $data{$_}:exists }).all {
            .($data, $driver, %values) for @!full-row-inflators;
            return model.new(|%values);
        }
        return callsame unless $data.keys.map({ %!storage-row-columns{$_}:exists }).all;
        for $data.kv -> $key, $value {
            next unless $value.defined;
            my %column = %!storage-row-columns{$key};
            my $inflated = %column<inflate>($value,
                |(%column<type> if %column<arity> > 1));
            %values{%column<name>} = $driver.inflate($inflated, :to(%column<type>));
        }
        model.new(|%values)
    }
}

# Reuse a RETURNING row without changing the dynamically composed storage HOW.
# The copy plan holds column names only; objects and values stay execution-local.
my Lock $copy-plan-lock .= new;
my %copy-plans;
sub refresh-storage-data($model, Associative $data) is export {
    my $type = $model.WHAT;
    my $names = $copy-plan-lock.protect: {
        %copy-plans{$type.WHICH.Str} //= $type.^columns.map(*.column.attr-name).eager.List
    };
    my $fresh = $type.^new-from-data($data);
    $model.^set-attr($_, $fresh."$_"()) for $names.List;
    $model.^clean-up;
    $model
}

# Keep native cursors scoped even when a statement fails inside a transaction.
sub storage-query($connection, Str $sql, *@binds --> Array) is export {
    my $statement = $connection.prepare($sql);
    LEAVE { try $statement.statement.?finish; try $statement.finish-transaction }
    $statement.execute(|@binds);
    my @rows;
    loop {
        my $row = $statement.row;
        last unless $row ~~ Associative && $row.elems;
        $row<mro> = mro-string($row<mro>) if $row<mro>:exists;
        @rows.push($row);
    }
    @rows
}

sub storage-model-rows(Mu:U $model, Str $sql, *@binds --> Array) is export {
    storage-query(get-RED-DB, $sql, |@binds).map(-> %data {
        my $row = $model.^new-from-data(%data);
        $row.^clean-up;
        $row.^saved-on-db;
        $row
    }).Array
}

sub storage-read-ids(Mu:U $model, *@ids --> Array) is export {
    my $connection = get-RED-DB;
    my $pg = $connection.^mro.map(*.^name).first(* eq 'Red::Driver::Pg').defined;
    my @rows;
    for @ids.map(*.UInt).unique.rotor(128, :partial) -> @chunk {
        my @p = $pg ?? (1..@chunk.elems).map({ '$' ~ $_ }) !! ('?' xx @chunk.elems);
        @rows.append(storage-model-rows($model, 'SELECT * FROM '
            ~ $connection.table-name-wrapper($model.^table) ~ ' WHERE id IN (' ~ @p.join(',') ~ ')', |@chunk));
    }
    @rows
}

# SQLite supports the same INSERT ... RETURNING contract used by Red's Pg
# driver. Restrict it to our storage tables and preserve Red's create hooks,
# model construction and dirty tracking. Stable column order also keeps the
# prepared SQL shape independent of Hash iteration order.
role SQLiteStorageReturning is export {
    multi method translate(Red::AST::Insert $insert, $context?) {
        return callsame unless $insert.into.^name eq any(
            <RedSourcing::StoredEvent RedSourcing::StoredCommand RedSourcing::StoredCounter>);
        my @values = $insert.values.pairs.grep({
            .value.value.defined || (.value.column.DEFINITE
                && .value.column.attr.type ~~ Json && !(.value.value === Json))
        }).sort(*.key);
        my $table = self.table-name-wrapper($insert.into.^table);
        return "INSERT INTO $table DEFAULT VALUES RETURNING *" => [] unless @values;
        my @binds = @values.map({ self.wildcard-value(.value) });
        'INSERT INTO ' ~ $table ~ ' (' ~ @values.map({ self.table-name-wrapper(.key) }).join(',')
            ~ ') VALUES (' ~ ('?' xx @values.elems).join(',') ~ ') RETURNING *' => @binds
    }
}

sub optimize-storage-driver($driver) is export {
    if $driver.^mro.map(*.^name).first(* eq 'Red::Driver::SQLite').defined {
        $driver does SQLiteStorageReturning unless $driver ~~ SQLiteStorageReturning;
    }
    install-read-cache($driver);
    $driver
}

# SQL and bind layouts belong to the driver context. Values and execution
# wrappers do not. Cloned transaction drivers may share immutable SQL entries.
my Lock $read-install-lock .= new;

class ReadArgument {
    has Int $.index;
    has Str $.encoding = '';
}
class ReadSqlCache {
    has Lock $!lock .= new;
    has %!sql;
    has @!order;
    method get(Str $key, &compile) {
        $!lock.protect: {
            if %!sql{$key}:exists {
                @!order = @!order.grep(* ne $key);
                @!order.push($key);
                return %!sql{$key};
            }
            my $result = compile();
            @!order.push($key);
            %!sql{@!order.shift}:delete while @!order > 128;
            %!sql{$key} = $result;
        }
    }
}
role CompiledReads {
    multi method translate(EventTypeMembership $node, $context?) {
        my ($column, @binds) := self.translate($node.column, 'table-dot-column').kv;
        my $literal = $node.name;
        my $placeholder = self.wildcard;
        pg-driver(self)
            ?? ("($column \@> ARRAY[$placeholder]::text[])" => [|@binds, $literal])
            !! ("$column LIKE $placeholder" => [|@binds, '%|' ~ $literal ~ '|%'])
    }
    has ReadSqlCache $!read-cache .= new;
    multi method translate(ExactEq $comparison, $context?) {
        my $field = $comparison.left ~~ Red::AST::JsonItem ?? $comparison.left
            !! $comparison.right ~~ Red::AST::JsonItem ?? $comparison.right !! Nil;
        return callsame unless $field.defined;
        my $argument = $comparison.left === $field ?? $comparison.right !! $comparison.left;
        return callsame unless $argument ~~ QueryBind || $argument ~~ Red::AST::Value;
        my $pg = self.^mro.map(*.^name).first(* eq 'Red::Driver::Pg').defined;
        if $pg {
            my ($left, @lb) := self.translate($field, 'json-value').kv;
            my $right = self.wildcard;
            my $bind = $argument ~~ QueryBind
                ?? ReadArgument.new(:index($argument.index), :encoding<json>)
                !! to-json($argument.value, :!pretty);
            return "($left = ($right)::text::jsonb)" => [|@lb, $bind];
        }
        my ($base, @base-binds) := self.translate($field.left, 'json-source').kv;
        my ($path, @path-binds) := self.sqlite-json-path($field.right).kv;
        my $value = $argument.value;
        if !$value.defined || $value ~~ Str || $value ~~ Bool || $value ~~ Numeric {
            my $kind = !$value.defined ?? "'null'" !! $value ~~ Bool ?? "'true','false'"
                !! $value ~~ Numeric ?? "'integer','real'" !! "'text'";
            my $placeholder = self.wildcard;
            my $bind = $argument ~~ QueryBind ?? ReadArgument.new(:index($argument.index)) !! $value;
            my $operator = $value.defined ?? '=' !! 'IS';
            return "(JSON_TYPE($base, $path) IN ($kind) AND JSON_EXTRACT($base, $path) $operator $placeholder)"
                => [|@base-binds, |@path-binds, |@base-binds, |@path-binds, $bind];
        }
        # JSON_TREE paths preserve array order and ignore object member order;
        # normalize integer/real so equivalent JSON numbers still compare equal.
        my ($left, @lb) := self.translate($field, 'json-value').kv;
        my $right = self.wildcard;
        my $bind = $argument ~~ QueryBind
            ?? ReadArgument.new(:index($argument.index), :encoding<json>) !! to-json($value, :!pretty);
        my $columns = "fullkey, CASE WHEN type IN ('integer','real') THEN 'number' ELSE type END, atom";
        my $l = "SELECT $columns FROM JSON_TREE($left)";
        my $r = "SELECT $columns FROM JSON_TREE($right)";
        "(NOT EXISTS ($l EXCEPT $r) AND NOT EXISTS ($r EXCEPT $l))" => [|@lb, $bind, $bind, |@lb]
    }
    multi method translate(QueryBind $value, $context?) {
        my $pg = self.^mro.map(*.^name).first(* eq 'Red::Driver::Pg').defined;
        my $json = $value.returns ~~ Json;
        my $sql = self.wildcard;
        my $encoding = '';
        if $pg && ($context // '') eq 'json-value' {
            my $type = $json ?? 'jsonb' !! $value.returns ~~ Bool ?? 'boolean'
                !! $value.returns ~~ Numeric ?? 'numeric' !! 'text';
            $sql = "($sql)::$type";
            $encoding = $json ?? 'json' !! $value.returns ~~ Bool ?? 'boolean' !! '';
        } elsif $json {
            $sql = $pg ?? "($sql)::text::jsonb" !! "JSON($sql)";
            $encoding = 'json';
        }
        $sql => [ReadArgument.new(:index($value.index), :$encoding)]
    }
    method read-sql(Str $key, &compile) { $!read-cache.get($key, &compile) }

}

# This cache is on the physical SQLite connection, not on a transaction clone.
# A busy handle is absent from the idle pool and therefore cannot be reused.
role SQLiteReadHandles {
    has Lock $!handle-lock .= new;
    has %!idle-reads;
    has @!idle-order;
    method teardown-connection-state() {
        $!handle-lock.protect: {
            .dispose for %!idle-reads.values;
            %!idle-reads = (); @!idle-order = ();
        }
        callsame
    }
    method acquire-read(Str $sql, &prepare) {
        my $handle = $!handle-lock.protect: {
            @!idle-order = @!idle-order.grep(* ne $sql);
            %!idle-reads{$sql}:delete
        };
        $handle // prepare()
    }
    method release-read(Str $sql, $handle, Bool $success) {
        $handle.finish;
        unless $success { $handle.dispose; return }
        $!handle-lock.protect: {
            if %!idle-reads{$sql}:exists { $handle.dispose; return }
            %!idle-reads{$sql} = $handle;
            @!idle-order.push($sql);
            while @!idle-order > 128 {
                my $old = %!idle-reads{@!idle-order.shift}:delete;
                $old.dispose;
            }
        }
    }
}

sub storage-template-rows(Mu:U $model, Str $key, Red::AST $filter, @values, Bool :$cache = True --> Array) is export {
    my $connection = get-RED-DB;
    my $*RED-INTERNAL = True;
    my &compile = {
        my $query = $model.^all.where($filter).sort(*.id).ast;
        my @translated = $connection.translate($connection.optimize($query));
        die 'Expected one SELECT for a projection replay' unless @translated.elems == 1;
        @translated.head
    };
    cached-storage-query($connection, $key, &compile, @values, :$cache).map(-> %data {
        materialize-storage-row($model, %data)
    }).Array
}

sub materialize-storage-row(Mu:U $model, %data) {
    my $row = $model.^new-from-data(%data);
    $row.^clean-up;
    $row.^saved-on-db;
    $row
}

# Shared SQL/bind cache and physical statement leases, also used by CTE reads.
sub cached-storage-query($connection, Str $key, &compile, @values, Bool :$cache = True --> Array) {
    $read-install-lock.protect: { $connection does CompiledReads unless $connection ~~ CompiledReads };
    my $types = @values.map({ .WHAT.^name ~ ':' ~ .defined.Int }).join('|');
    my $entry = $cache ?? $connection.read-sql($key ~ '|' ~ $types, &compile) !! compile();
    my @binds = $entry.value.map: -> $argument {
        my $value = $argument ~~ ReadArgument ?? @values[$argument.index] !! $argument;
        if $argument ~~ ReadArgument {
            given $argument.encoding {
                when 'json' {  $value = to-json($value, :!pretty) }
                when 'boolean' { $value = $value ?? 'true' !! 'false' }
            }
        }
        $connection.deflate($value)
    };
    my @rows;
    if $connection.^mro.map(*.^name).first(* eq 'Red::Driver::SQLite').defined {
        my $attribute = $connection.^attributes.first(*.name eq '$!dbh');
        my $native = $attribute.get_value($connection);
        $read-install-lock.protect: { $native does SQLiteReadHandles unless $native ~~ SQLiteReadHandles };
        my &read = {
            CATCH { default { $connection.map-exception($_).throw } }
            my $handle = $cache
                ?? $native.acquire-read($entry.key, { $connection.prepare($entry.key).statement })
                !! $connection.prepare($entry.key).statement;
            my $success = False;
            LEAVE $native.release-read($entry.key, $handle, $success && $cache);
            $handle.execute(|@binds);
            loop {
                my $row = $handle.row(:hash);
                last unless $row ~~ Associative && $row.elems;
                @rows.push($row);
            }
            $success = True;
        };
        my $guard = $connection.?transaction-guard;
        $guard.defined ?? $guard.protect(&read) !! read();
    } else {
        @rows = storage-query($connection, $entry.key, |@binds);
    }
    @rows
}

sub storage-stream-tail(Mu:U $model, Str $stream, UInt $cursor) is export {
    my $connection = get-RED-DB;
    return Nil unless pg-driver($connection)
        || $connection.^mro.map(*.^name).first(* eq 'Red::Driver::SQLite').defined;
    my &compile = {
        my @p = pg-driver($connection) ?? < $1 $2 > !! < ? ? >;
        'SELECT * FROM ' ~ $connection.table-name-wrapper($model.^table)
            ~ ' WHERE stream = ' ~ @p[0] ~ ' AND id > ' ~ @p[1] ~ ' ORDER BY id'
            => [ReadArgument.new(:index(0)), ReadArgument.new(:index(1))]
    };
    cached-storage-query($connection, 'entity-cache:stream-tail', &compile, [$stream, $cursor])
        .map({ materialize-storage-row($model, $_) }).Array
}

# A cache hit needs checkpoint metadata, not a hydrated snapshot payload.
sub storage-checkpoint-version(Str $class, Str $stream --> UInt) is export {
    my $connection = get-RED-DB;
    my $pg = pg-driver($connection);
    my @p = $pg ?? < $1 $2 > !! < ? ? >;
    my $sql = 'SELECT version FROM red_sourcing_event WHERE class = ' ~ @p[0]
        ~ ' AND stream = ' ~ @p[1] ~ ' ORDER BY id DESC LIMIT 1';
    my @rows = cached-storage-query($connection, 'entity-cache:checkpoint',
        -> { $sql => [ReadArgument.new(:index(0)), ReadArgument.new(:index(1))] }, [$class, $stream]);
    (@rows ?? @rows[0]<version> !! 0).UInt
}

# One latest checkpoint per identity. Repeated decision positions share the row,
# but each position materializes its own isolated projection from it.
sub storage-decision-snapshots(Mu:U $model, @identities --> Hash) is export {
    my $connection = get-RED-DB;
    return %(unsupported => True) unless pg-driver($connection)
        || $connection.^mro.map(*.^name).first(* eq 'Red::Driver::SQLite').defined;
    my @values = @identities.map({ .<type>.^name, .<stream> }).flat;
    my &compile = {
        my $table = $connection.table-name-wrapper($model.^table);
        my %names = $model.^columns.map({ .column.attr-name => $connection.table-name-wrapper(.column.name) });
        my $columns = $model.^columns.map(-> $attribute {
            my $name = $attribute.column.attr-name;
            my $column = %names{$name};
            $name eq 'mro' && pg-driver($connection)
                ?? "('|' || array_to_string(e.$column, '|') || '|') AS $column"
                !! "e.$column AS $column"
        }).join(', ');
        my @conditions = @identities.keys.map(-> $i {
            my @p = pg-driver($connection) ?? ('$' ~ (2*$i+1), '$' ~ (2*$i+2)) !! ('?', '?');
            "({%names<class>} = {@p[0]} AND {%names<stream>} = {@p[1]})"
        });
        my $sql = "SELECT $columns FROM $table e WHERE e.{%names<id>} IN (SELECT MAX({%names<id>})"
            ~ " FROM $table WHERE " ~ @conditions.join(' OR ')
            ~ " GROUP BY {%names<class>}, {%names<stream>})";
        $sql => [|@values.keys.map({ ReadArgument.new(:index($_)) })]
    };
    my %rows;
    for cached-storage-query($connection, 'decision-snapshots:' ~ $model.WHICH.Str ~ ':' ~ @identities.elems,
            &compile, @values) -> %data {
        my $row = materialize-storage-row($model, %data);
        %rows{$row.class}{$row.stream} = $row;
    }
    %(rows => %rows)
}

sub storage-aggregate-rows(Mu:U $model, Str $class, Str $stream --> Hash) is export {
    my $connection = get-RED-DB;
    return %(unsupported => True) unless pg-driver($connection)
        || $connection.^mro.map(*.^name).first(* eq 'Red::Driver::SQLite').defined;
    my &compile = {
        my $table = $connection.table-name-wrapper($model.^table);
        my %names = $model.^columns.map({ .column.attr-name => $connection.table-name-wrapper(.column.name) });
        my &columns = -> $alias {
            $model.^columns.map(-> $attribute {
                my $name = $attribute.column.attr-name;
                my $column = %names{$name};
                $name eq 'mro' && pg-driver($connection)
                    ?? "('|' || array_to_string($alias.$column, '|') || '|') AS $column"
                    !! "$alias.$column AS $column"
            }).join(', ')
        };
        my @p = pg-driver($connection) ?? < $1 $2 > !! < ? ? >;
        my $sql = "WITH snapshot AS (SELECT * FROM $table WHERE {%names<class>} = {@p[0]}"
            ~ " AND {%names<stream>} = {@p[1]} ORDER BY {%names<id>} DESC LIMIT 1) "
            ~ 'SELECT ' ~ columns('s') ~ ', 0 AS __rs_initial FROM snapshot s UNION ALL SELECT '
            ~ columns('e') ~ ", 1 AS __rs_initial FROM snapshot s CROSS JOIN $table e"
            ~ " WHERE e.{%names<stream>} = s.{%names<stream>}"
            ~ " AND e.{%names<id>} > COALESCE(s.{%names<replay-cursor>}, s.{%names<id>})"
            ~ " ORDER BY __rs_initial, {%names<id>}";
        $sql => [ReadArgument.new(:index(0)), ReadArgument.new(:index(1))]
    };
    my $snapshot;
    my @events;
    for cached-storage-query($connection, 'aggregate-restore:' ~ $model.WHICH.Str,
            &compile, [$class, $stream]) -> %data {
        my $phase = %data<__rs_initial>:delete;
        my $row = materialize-storage-row($model, %data);
        $phase == 0 ?? ($snapshot = $row) !! @events.push($row);
    }
    %( :$snapshot, events => @events )
}

sub install-read-cache($connection) {
    $read-install-lock.protect: { $connection does CompiledReads unless $connection ~~ CompiledReads };
}

before_source.lib/RedSourcing/QueryTemplate.rakumod:
unit module RedSourcing::QueryTemplate;
use nqp;
use experimental :rakuast;
use Red;
use Red::AST;
use Red::AST::Value;
use Red::AST::Infixes;
use Red::AST::Unary;
use Red::Type::Json;
use Red::ColumnMethods;
use RedSourcing::C;
use RedSourcing::EventType;

# This registry is used only while composing a compilation unit. The resulting
# shapes, not the registry or compiler nodes, are saved with the projection HOW.
my @constraints;
sub constraint-variables(Mu $ast --> List) {
    my @references;
    my %seen;
    if $ast.^name.starts-with('QAST::') {
        sub walk(Mu $node, %outer, Bool $dynamic = False) {
            return unless nqp::can($node, 'ann');
            return if %seen{nqp::where(nqp::decont($node))}++;
            my %locals = %outer;
            if nqp::can($node, 'symbol') {
                # A block's symbol table includes declarations in that lexical
                # scope, but not captures from its outer scopes.
                my Mu $symbols := $node.symtable;
                for nqp::hllize($symbols).keys -> $name { %locals{$name} = True }
            }
            if nqp::can($node, 'scope') && nqp::can($node, 'name') {
                my $name = $node.name;
                @references.push($name)
                    if $node.scope eq any(<lexical contextual package>)
                    && $name.substr(0, 1) eq any('$', '@', '%', '&')
                    && !$node.decl && !(%locals{$name}:exists);
            }
            my $in-dynamic = $dynamic || (nqp::can($node, 'op') && $node.op eq 'call' && $node.name eq '&DYNAMIC');
            if $in-dynamic && $node.^name eq 'QAST::SVal' {
                my $name = $node.value;
                @references.push($name) unless %locals{$name}:exists;
            }
            # Qualified package variables are lowered to a stash lookup rather
            # than QAST::Var. Ordinary event/hash subscripts have no `who`.
            if nqp::can($node, 'op') && $node.op eq 'callmethod' && $node.name eq 'AT-KEY' {
                my @children = nqp::hllize($node.list).List;
                if @children.elems == 2 && nqp::can(@children[0], 'op')
                    && @children[0].op eq 'who' && nqp::can(@children[1], 'value') {
                    my Mu $name = @children[1].value;
                    @references.push($name) if $name ~~ Str && $name.substr(0, 1) eq any('$', '@', '%', '&');
                }
            }
            for nqp::hllize($node.list).List -> $child { walk($child, %locals, $in-dynamic.so) }
            my Mu $block := $node.ann('past_block');
            walk($block, %locals) if nqp::isconcrete($block);
        }
        walk($ast, {});
    } else {
        my @nodes;
        sub visit(Mu $node) {
            return if %seen{nqp::where(nqp::decont($node))}++;
            @nodes.push($node);
            $node.visit-children(-> Mu $child { visit($child) });
        }
        visit($ast);
        for @nodes -> $node {
            next unless $node ~~ RakuAST::Var::Lexical|RakuAST::Var::Dynamic|RakuAST::Var::Package;
            next if $node ~~ RakuAST::Var::Lexical && $node.is-resolved
                && @nodes.first({ $_ === $node.resolution }).defined;
            @references.push($node ~~ RakuAST::Var::Package
                ?? $node.sigil ~ $node.twigil ~ $node.name.canonicalize
                !! $node.name);
        }
    }
    @references.unique.List
}
sub record-query-constraint(Mu $code, Str $source, Mu :$ast) is export {
    @constraints.push([$code, $source, $ast.defined ?? constraint-variables($ast) !! ()]);
}
sub constraint-entry(Mu $code) {
    for @constraints.reverse -> $entry {
        my Mu $candidate = $entry[0];
        unless $candidate ~~ Code {
            $candidate = try {
                my $primed = $candidate.?IMPL-PRIMED;
                ($primed ?? $primed !! $candidate).meta-object
            };
        }
        return $entry if $candidate.defined && $candidate === $code;
    }
    Nil
}
sub constraint-source(Mu $code) { constraint-entry($code)[1] }

sub validate-handler-constraints(Mu:U $entity, @trusted --> List) is export {
    my @validated;
    for <APPLY REACT> -> $method {
        my $handler = $entity.^find_method($method);
        next unless $handler.defined;
        for $handler.candidates -> &candidate {
            @validated.push(&candidate);
            next if @trusted.first({ $_ === &candidate }).defined;
            sub parameters($signature) {
                gather for $signature.params -> $parameter {
                    take $parameter;
                    if $parameter.sub_signature {
                        take $_ for parameters($parameter.sub_signature);
                    }
                }
            }
            my @parameters = parameters(&candidate.signature);
            my %allowed = @parameters.map({ .name => True });
            %allowed<$_> = True;
            for @parameters -> $parameter {
                my $constraints := nqp::getattr(nqp::decont($parameter), Parameter, '@!post_constraints');
                next if nqp::isnull($constraints);
                for ^nqp::elems($constraints) -> $i {
                    my Mu $constraint := nqp::atpos($constraints, $i);
                    my $entry = constraint-entry($constraint);
                    unless $entry.defined {
                        die "{$entity.^name}.$method where cannot be validated: constraint source unavailable; declare the filter on the entity"
                            if $constraint ~~ Code;
                        next;
                    }
                    for $entry[2].List -> $name {
                        die "{$entity.^name}.$method where cannot capture external variable $name; use an event parameter or an entity attribute"
                            unless %allowed{$name}:exists;
                    }
                }
            }
        }
    }
    @validated.List
}

# A deliberately closed expression grammar. No captured variables, calls,
# interpolation, declarations or arbitrary Raku are evaluated by this compiler.
grammar FilterSyntax {
    token identifier { <[a..z A..Z _]> <[\w \-]>* }
    rule TOP { [ '{' <disjunction> ';'? '}' | <disjunction> ] }
    rule disjunction { <conjunction>+ % '||' }
    rule conjunction { <comparison>+ % '&&' }
    rule comparison { <operand> [ <operator> <operand> ]? }
    token operator { 'eqv' | 'eq' | 'ne' | '==' | '!=' | '<=' | '>=' | '<' | '>' }
    rule operand { [ '!' <operand> | '(' <disjunction> ')' | <receiver> | <field> | <literal> ] }
    token receiver { '$!' <identifier> }
    token field { [ '$' $<variable>=[ <identifier> | '_' ] ]? '.' <identifier> }
    token literal { <number> | <single> | <double> | <boolean> }
    token number { '-'? \d+ [ '.' \d+ ]? }
    token single { "'" $<text>=[ <-['\\]>* ] "'" }
    token double { '"' $<text>=[ <-["\\$@%{]>* ] '"' }
    token boolean { 'True' | 'False' }
}
class FilterActions {
    method TOP($/) { make $<disjunction>.made }
    method disjunction($/) { make ['or', |$<conjunction>».made] }
    method conjunction($/) { make ['and', |$<comparison>».made] }
    method comparison($/) {
        make $<operator> ?? [$<operator>.Str, |$<operand>».made] !! $<operand>[0].made
    }
    method operand($/) {
        make $<operand> ?? ['not', $<operand>.made]
            !! $<disjunction> ?? $<disjunction>.made
            !! $<receiver> ?? $<receiver>.made
            !! $<field> ?? $<field>.made !! $<literal>.made
    }
    method receiver($/) { make ['receiver', $<identifier>.Str] }
    method field($/) { make ['field', $<identifier>.Str, ($<variable> ?? $<variable>.Str !! '')] }
    method literal($/) {
        make ['literal', $<number> ?? +$<number>.Str
            !! $<single> ?? $<single><text>.Str
            !! $<double> ?? $<double><text>.Str !! ($<boolean>.Str eq 'True')]
    }
}

class EventColumn does Red::AST does Red::ColumnMethods is export {
    has Str $.name;
    method args { $!name }
    method returns { $!name eq 'data' ?? Json !! Str }
    method find-column-name { $!name }
}

class ExactEq is Red::AST::Eq is export {
    method not { Red::AST::Not.new(self) }
}

class ReceiverParameter does Red::AST does Red::ColumnMethods is export {
    has Str $.name;
    has Mu $.type;
    has Attribute $.attribute;
    method args { $!name, $!attribute.package.^name }
    method returns { $!type }
    method find-column-name { $!name }
}

sub shape-nodes($shape) {
    gather {
        take $shape;
        for $shape.list.skip(1).grep(* ~~ Array) -> $child {
            take $_ for shape-nodes($child);
        }
    }
}

sub query-shape(&candidate, @inherited --> Hash) is export {
    # Inherited methods from an already-precompiled module carry their shape on
    # the parent's descriptor; compiler registry mutations do not cross units.
    for @inherited -> $entry {
        return $entry<shape> if $entry<candidate> === &candidate;
    }
    my @parameters = &candidate.signature.params.grep({ !.invocant && !.slurpy });
    return %( reason => 'unsupported event signature' )
        unless @parameters.elems == 1 && @parameters.head.positional;
    my $parameter = @parameters.head;
    return %( reason => 'sub-signature uses runtime binding' ) if $parameter.sub_signature;
    my $constraints := nqp::getattr(nqp::decont($parameter), Parameter, '@!post_constraints');
    return %( expression => ['literal', True] )
        if nqp::isnull($constraints) || !nqp::elems($constraints);
    my @expressions;
    for ^nqp::elems($constraints) -> $i {
        my $source = constraint-source(nqp::atpos($constraints, $i));
        return %( reason => 'constraint source unavailable' ) unless $source.defined;
        my $match = FilterSyntax.parse($source, :actions(FilterActions.new));
        return %( reason => 'expression outside the compiled filter subset' ) unless $match;
        my $shape = $match.made;
        for shape-nodes($shape).grep({ $_[0] eq 'field' }) -> $field {
            return %( reason => 'field receiver is not the event parameter' )
                if $field[2] ne '' && ('$' ~ $field[2]) ne $parameter.name && $field[2] ne '_';
        }
        @expressions.push($shape);
    }
    %( expression => ['and', |@expressions] )
}

sub filter-boolean($value) {
    my $ast = ast-value($value);
    $ast.returns ~~ Bool ?? $ast !! Red::AST::Cast.new($ast, 'boolean')
}

sub shape-expression($shape, $view, %parameters) {
    my $op = $shape[0];
    my @args = $shape.list.skip(1);
    given $op {
        when 'literal' { @args[0] }
        when 'field' { $view{@args[0]} }
        when 'receiver' { %parameters{@args[0]} // die "Unknown receiver attribute {@args[0]}" }
        when 'and' | 'or' {
            my @values = @args.map({ filter-boolean(shape-expression($_, $view, %parameters)) });
            my $result = @values.shift;
            for @values -> $value {
                $result = $op eq 'and' ?? Red::AST::AND.new($result, $value)
                    !! Red::AST::OR.new($result, $value);
            }
            $result
        }
        when 'not' { filter-boolean(shape-expression(@args[0], $view, %parameters)).not }
        default {
            my $left = shape-expression(@args[0], $view, %parameters);
            my $right = shape-expression(@args[1], $view, %parameters);
            my %operators = eqv => Red::AST::Eq, eq => Red::AST::Eq, ne => Red::AST::Ne,
                '==' => Red::AST::Eq, '!=' => Red::AST::Ne,
                '<' => Red::AST::Lt, '>' => Red::AST::Gt, '<=' => Red::AST::Le, '>=' => Red::AST::Ge;
            $op eq 'eqv'
                ?? ExactEq.Mu::new(:left(ast-value($left)), :right(ast-value($right)))
                !! %operators{$op}.new(
                    Red::AST::Cast.new(ast-value($left), $op eq any(<eq ne>) ?? 'str' !! 'num'),
                    Red::AST::Cast.new(ast-value($right), $op eq any(<eq ne>) ?? 'str' !! 'num'))
        }
    }
}

sub compile-query-template(Mu $stored, Mu:U $event, %shape, @attributes) is export {
    return %shape unless %shape<expression>:exists;
    my %fields = $event.^attributes.map({ .name.substr(2) => True });
    for shape-nodes(%shape<expression>).grep({ $_[0] eq 'field' }) -> $node {
        return %( reason => "event accessor {$node[1]} is not a stored attribute" )
            unless %fields{$node[1]}:exists;
    }
    my %parameters;
    for shape-nodes(%shape<expression>).grep({ $_[0] eq 'receiver' }) -> $node {
        my $name = $node[1];
        my @matches = @attributes.grep(*.key eq $name);
        return %( reason => "ambiguous receiver attribute $name" ) unless @matches.elems == 1;
        my $attribute = @matches.head.value;
        %parameters{$name} = ReceiverParameter.new(:$name, :$attribute, :type($attribute.type));
    }
    my $*RED-INTERNAL = True;
    my $view = C.new(:json(EventColumn.new(:name<data>)));
    my $condition = filter-boolean(shape-expression(%shape<expression>, $view, %parameters));
    my $type-filter = ast-value(Any ~~ $event) OR event-type-ast(EventColumn.new(:name<mro>), $event.^name);
    my $ast = $type-filter AND $condition;
    my $frozen = freeze-query-ast($ast);
    %( ast => $frozen, bindings => prepare-query-bindings($frozen),
        parameters => %parameters.values.eager.List )
}

# Compile the clone paths once as well. Runtime binding walks only these paths;
# it never reflects over AST attributes or clones constant-only subtrees.
sub prepare-query-bindings($ast) is export {
    return %(node => $ast, parameter => True)
        if $ast ~~ ReceiverParameter || $ast ~~ EventColumn;
    my %children;
    for $ast.^attributes -> $attribute {
        my $original = $attribute.get_value($ast);
        my $name = $attribute.name.substr(2);
        if $original ~~ Red::AST:D {
            my $child = prepare-query-bindings($original);
            %children{$name} = $child if $child<parameter> || $child<children>.elems;
        } elsif $original ~~ Positional {
            my @items = $original.map({ $_ ~~ Red::AST:D
                ?? prepare-query-bindings($_) !! %(node => $_, children => Map.new) });
            %children{$name} = %(items => @items.List)
                if @items.grep({ .<parameter> || .<children>.elems }).elems;
        }
    }
    %(node => $ast, children => %children.Map)
}

sub bind-query-template($plan, &value) is export {
    return ast-value(value($plan<node>)) if $plan<parameter>;
    return $plan<items>.map({ bind-query-template($_, &value) }).Array if $plan<items>:exists;
    return $plan<node> unless $plan<children>.elems;
    my %changes = $plan<children>.map({ .key => bind-query-template(.value, &value) });
    $plan<node>.clone(|%changes)
}

# Execution-local slot. Its value is never serialized or included in the shared
# AST. Unlike Value, optimizers cannot constant-fold it based on one execution.
class QueryBind does Red::AST is export {
    has Int $.index;
    has Mu $.value;
    method args { $!index, $!value.WHAT.^name, $!value.defined }
    method returns { $!value.WHAT }
    method find-column-name { }
}

sub projection-query-filters($stored, $descriptor, $receiver, @values --> Array) is export {
    my $*RED-INTERNAL = True;
    die $descriptor<rule-error> if $descriptor<rule-error>.defined;
    my @filters;
    for $descriptor<rules>.kv -> $i, &bind {
        my $template = $descriptor<templates>[$i];
        if $template<ast>:exists {
            @filters.push(bind-query-template($template<bindings>, -> $parameter {
                if $parameter ~~ EventColumn {
                    $stored."{$parameter.name}"()
                } else {
                    my $value = $parameter.attribute.get_value($receiver);
                    my $slot = QueryBind.new(:index(@values.elems), :$value);
                    @values.push($value);
                    $slot
                }
            }));
        } else {
            @filters.push($stored.event-filter(bind($receiver)));
        }
    }
    @filters
}

sub freeze-query-ast(Mu $value) {
    if $value ~~ Red::AST:D && $value !~~ Red::Column {
        my $base = $value.^mro.first({ !.^name.contains('+{') && .^name.starts-with(any('Red::AST::', 'RedSourcing::QueryTemplate::', 'RedSourcing::EventType::')) });
        return $value unless $base ~~ Mu:U && $base !~~ Nil;
        return $value unless $base.^name.starts-with(any('Red::AST::', 'RedSourcing::QueryTemplate::', 'RedSourcing::EventType::'));
        my %args;
        for $base.^attributes -> $attribute {
            %args{$attribute.name.substr(2)} = freeze-query-ast($attribute.get_value($value));
        }
        return $base.Mu::new(|%args);
    }
    return $value.map({ freeze-query-ast($_) }).Array if $value ~~ Positional;
    $value
}
